package com.spawnershop.config;
import org.bukkit.Material; import org.bukkit.configuration.ConfigurationSection; import org.bukkit.configuration.file.YamlConfiguration; import org.bukkit.plugin.Plugin; import java.io.File; import java.math.BigDecimal; import java.util.*;
/** Immutable per-material sell prices loaded from sell-items.yml. */
public final class SellPriceRepository { private final Plugin plugin; private volatile Map<Material,BigDecimal> prices=Map.of(); public SellPriceRepository(Plugin plugin){this.plugin=plugin;} public void reload(){YamlConfiguration y=YamlConfiguration.loadConfiguration(new File(plugin.getDataFolder(),"sell-items.yml"));ConfigurationSection s=y.getConfigurationSection("prices");Map<Material,BigDecimal> next=new EnumMap<>(Material.class);if(s!=null)for(String key:s.getKeys(false))try{Material m=Material.matchMaterial(key);BigDecimal price=new BigDecimal(Objects.requireNonNull(s.getString(key)));if(m!=null&&price.signum()>=0)next.put(m,price);}catch(RuntimeException e){plugin.getLogger().warning("Invalid sell price: "+key);}prices=Map.copyOf(next);} public Map<Material,BigDecimal> prices(){return prices;} }
